using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Security.Cryptography;using System.Text;using System.Web.Script.Serialization;
namespace PZ3D {static class SaveDiscoveryListTests {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4194304};static int checks;static readonly List<string> failures=new List<string>();
 static void Check(bool value,string name){checks++;if(!value)throw new Exception("FAIL "+name);}
 static void Put(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));}
 static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 static Dictionary<string,object> D(object row){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(row));}
 static Dictionary<string,object>[] Rows(Dictionary<string,object> row,string key){return ((IEnumerable)row[key]).Cast<Dictionary<string,object>>().ToArray();}
 static string[] Warnings(Dictionary<string,object> row){return ((IEnumerable)row["warnings"]).Cast<string>().ToArray();}
 sealed class Fixture:IDisposable {
  internal readonly string Root,Game,User,Data,Index;internal readonly ModernController Controller;internal readonly Engine Engine;
  internal Fixture(string parent,string name,bool saves=true){Root=Path.Combine(parent,name);Game=Path.Combine(Root,"game");User=Path.Combine(Root,"user");Data=Path.Combine(Root,"data");Index=Path.Combine(Data,"save-environments","index.json");Put(Path.Combine(Game,"ProjectZomboid64.exe"),"OWNED NEVER EXECUTE");Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(Game,"version.txt"),"42.20.4");Put(Path.Combine(User,"mods","default.txt"),"mods\n{\n}\nmaps\n{\n}\n");if(saves)foreach(string save in new[]{"Alpha","Beta"})Put(Path.Combine(User,"Saves","Sandbox",save,"mods.txt"),"mods\n{\n}\nmaps\n{\n}\n");Controller=new ModernController(Game,User,Data,true);Engine=new Engine(Game,User,Data,true);}
  internal Dictionary<string,object> List(string selected=null){return D(Controller.Execute("environmentList",selected==null?new Dictionary<string,object>():new Dictionary<string,object>{{"saveId",selected}}));}
  internal object Pointer(string id,string name,bool valid=true,bool malformed=false){string path=Path.Combine(Root,name),hash=new string('a',64);if(valid){Put(Path.Combine(path,"game","ProjectZomboid64.exe"),"OWNED NEVER EXECUTE");Put(Path.Combine(path,"game","ProjectZomboid64.json"),"{\"vmArgs\":[]}");string manifest=Path.Combine(path,SaveEnvironments.ManifestName);byte[] bytes;if(malformed)bytes=Encoding.UTF8.GetBytes("not JSON; owned fixture");else{string identity=(string)typeof(SaveEnvironments).GetMethod("Identity",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{path});var row=new SaveEnvironmentRecord{Id=id,Name=name,SaveId="Sandbox/Alpha",SourceGame=Game,UserPath=User,RootPath=path,GamePath=Path.Combine(path,"game"),RuntimeHome=Path.Combine(path,"runtime","home"),GameVersion="42.20.4",CreatedUtc="2026-10-30T00:00:00Z",ManifestPath=manifest,RootIdentity=identity,ModRoots=new SaveEnvironmentModRoot[0],GameSourceFiles=new SaveEnvironmentFile[0],ModIds=new string[0],DefaultModIds=new string[0],Maps=new string[0],PreloadModIds=new string[0]};bytes=SaveEnvironments.EncodeManifest(row,new SaveEnvironmentFile[0]);}File.WriteAllBytes(manifest,bytes);hash=Hash(bytes);}return new{Id=id,RootPath=path,ManifestHash=hash,UserPath=User,SourceGame=Game,SaveId="Sandbox/Alpha"};}
  internal void Catalog(object[] pointers,string binding=null){var bindings=new Dictionary<string,string>();if(binding!=null)bindings[Hash(Encoding.UTF8.GetBytes(Game.ToUpperInvariant()+"\n"+User.ToUpperInvariant()+"\nSandbox/Alpha"))]=binding;Put(Index,Json.Serialize(new{Schema=1,Records=pointers,Bindings=bindings}));}
  public void Dispose(){Controller.Dispose();}
 }
 static void Normal(string root){using(var f=new Fixture(root,"normal")){var view=f.List();Check(Rows(view,"saves").Length==2&&(string)view["selectedSaveId"]=="Sandbox/Alpha","normal local saves remain selectable");Check(Rows(view,"snapshots").Length==0&&Warnings(view).Length==0,"normal no-history view has no added failure");}}
 static void Stale(string root){using(var f=new Fixture(root,"stale")){var view=f.List("Sandbox/Gone");Check(Rows(view,"saves").Length==2&&(string)view["selectedSaveId"]=="Sandbox/Alpha","stale requested save recovers surviving saves");Check(view.ContainsKey("selectionChanged")&&(bool)view["selectionChanged"]&&Warnings(view).Length>0,"fallback is explicit to UI and player");}}
 static void Empty(string root){using(var f=new Fixture(root,"empty",false)){var view=f.List("Sandbox/Gone");Check(Rows(view,"saves").Length==0&&(string)view["selectedSaveId"]=="","empty result clears unavailable selected save");Check(view.ContainsKey("selectionChanged")&&(bool)view["selectionChanged"]&&Warnings(view).Length>0,"empty fallback is explicit");}}
 static void History(string root,bool active,bool malformed){using(var f=new Fixture(root,malformed?"malformed":"missing-"+active)){string good=new string('1',32),bad=new string('2',32);f.Catalog(new[]{f.Pointer(good,"Valid history"),f.Pointer(bad,malformed?"Malformed history":"Missing history",malformed,malformed)},active?bad:null);byte[] before=File.ReadAllBytes(f.Index);var view=f.List("Sandbox/Alpha");Check(Rows(view,"saves").Length==2,"unavailable history retains local saves");Check(Rows(view,"snapshots").Length==1&&(string)Rows(view,"snapshots")[0]["id"]==good,"valid history sibling remains visible");Check(Warnings(view).Any(w=>w.Contains(malformed?"Malformed history":"Missing history")),"unavailable historical snapshot is named in a warning");Check(view.ContainsKey("unavailableSnapshotCount")&&(int)view["unavailableSnapshotCount"]==1,"unavailable history remains explicitly counted rather than reported as never created");Check(File.ReadAllBytes(f.Index).SequenceEqual(before),"read preserves exact snapshot catalogue bytes");if(active){Check((string)view["activeSnapshotId"]==bad&&Warnings(view).Any(w=>w.Contains("当前绑定")),"broken active binding stays explicit");bool refused=false;try{new SaveEnvironments(f.Engine).Bound("Sandbox/Alpha");}catch(IOException){refused=true;}Check(refused,"actual bound snapshot lookup still refuses missing payload");bool bindRefused=false;try{var store=new SaveEnvironments(f.Engine);store.Bind("Sandbox/Alpha",bad,store.BindingStamp("Sandbox/Alpha"));}catch(IOException){bindRefused=true;}Check(bindRefused&&File.ReadAllBytes(f.Index).SequenceEqual(before),"actual bind mutation still refuses missing target without catalog edits");}}}
 static void MissingManifest(string root){using(var f=new Fixture(root,"missing-manifest")){string bad=new string('3',32),name="Missing manifest",manifest=Path.Combine(f.Root,name,SaveEnvironments.ManifestName);var pointer=f.Pointer(bad,name);File.Move(manifest,manifest+".held");f.Catalog(new[]{pointer},bad);byte[] before=File.ReadAllBytes(f.Index);var diagnostic=new SaveEnvironments(f.Engine).ListRegistered("Sandbox/Alpha").Single();Check(diagnostic.Error.Contains("快照不可变清单已改变"),"original manifest error remains diagnostic evidence");var view=f.List("Sandbox/Alpha");Check(Warnings(view).Any(w=>w.Contains("快照配置文件已改变或缺失")&&!w.Contains("不可变清单")),"list explains missing manifest without internal terminology");Check(Warnings(view).Any(w=>w.Contains("恢复快照文件或位置")),"broken binding gives both file and location recovery action");Check(File.ReadAllBytes(f.Index).SequenceEqual(before)&&File.Exists(manifest+".held")&&!File.Exists(manifest),"friendly warning preserves catalogue and missing file state");}}
 static void MalformedSave(string root){using(var f=new Fixture(root,"bad-save-mods")){string id="Sandbox/BadMods",path=Path.Combine(f.User,"Saves","Sandbox","BadMods","mods.txt"),text="owned malformed metadata; never rewrite";Put(path,text);var list=D(SaveProfiles.List(f.Engine));var row=Rows(list,"saves").SingleOrDefault(value=>(string)value["id"]==id);Check(row!=null,"physically present save remains detected when only mod metadata is malformed");Check(row["modCount"]==null&&row.ContainsKey("modMetadataAvailable")&&!(bool)row["modMetadataAvailable"],"unreadable mod count is unknown, not invented zero");Check(Warnings(list).Any(w=>w.Contains("BadMods"))&&row.ContainsKey("warning")&&!string.IsNullOrWhiteSpace((string)row["warning"]),"malformed mod metadata is explicitly explained");var view=f.List(id);Check(Rows(view,"saves").Length==3&&(string)view["selectedSaveId"]==id,"snapshot save selector retains this physical save without treating it as missing");Check(SaveProfiles.ResolveSave(f.Engine,id)==Path.GetDirectoryName(path),"read-only directory lookup remains available");bool read=false,launch=false,save=false;try{SaveProfiles.Read(f.Engine,id);}catch{read=true;}try{SaveProfiles.ValidateForLaunch(f.Engine,id);}catch{launch=true;}try{SaveProfiles.Save(f.Engine,id,"invalid-owned-fixture-stamp",new string[0],true);}catch{save=true;}Check(read&&launch&&save,"invalid metadata still prevents mod editing and actual launch validation");Check(File.ReadAllText(path)==text,"list and refused edits preserve original malformed file bytes");}}
 static void Run(string name,Action action){try{action();Console.WriteLine("PASS "+name);}catch(Exception ex){failures.Add(name+": "+ex.Message);Console.WriteLine(ex);}}
 public static int Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Run("normal",()=>Normal(root));Run("malformed save metadata",()=>MalformedSave(root));Run("stale requested selection",()=>Stale(root));Run("empty requested selection",()=>Empty(root));Run("missing unbound history",()=>History(root,false,false));Run("malformed unbound history",()=>History(root,false,true));Run("active broken binding",()=>History(root,true,false));Run("missing manifest presentation",()=>MissingManifest(root));Console.WriteLine("Save discovery list: "+checks+" checks; "+failures.Count+" failed cases");return failures.Count==0?0:1;}
}}
